#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n,m;scanf("%d %d",&n,&m);
vector<vector<int>>g(n+1);
for(int i=0;i<m;++i){int u,v;scanf("%d %d",&u,&v);
g[u].push_back(v);g[v].push_back(u);}
int s;scanf("%d",&s);
for(int i=1;i<=n;++i)sort(g[i].begin(),g[i].end());
vector<bool>vis(n+1,false);queue<int>q;q.push(s);vis[s]=true;
vector<int>order;
while(!q.empty()){int u=q.front();q.pop();order.push_back(u);
for(int v:g[u])if(!vis[v]){vis[v]=true;q.push(v);}}
for(size_t i=0;i<order.size();++i){if(i)printf(" ");printf("%d",order[i]);}
printf("\n");return 0;}

